create table public.catalyst_classifications(id uuid primary key default gen_random_uuid(),classification_key text not null unique,policy_version text not null,news_observation_id uuid not null references public.news_observations(id),news_revision_id uuid not null references public.news_article_revisions(id),article_revision_number integer not null,asset_id uuid not null references public.assets(id),event_type text not null,materiality text not null check(materiality in('LOW','MEDIUM','HIGH','VERY_HIGH','UNKNOWN')),novelty text not null check(novelty in('NEW','FOLLOW_UP','REPEAT','CORRECTION','UNKNOWN')),event_status text not null check(event_status in('ANNOUNCED','CONFIRMED','COMPLETED','CANCELLED','RUMOR','UNKNOWN')),entity_confidence integer not null check(entity_confidence between 0 and 100),classification_confidence integer not null check(classification_confidence between 0 and 100),direction text not null check(direction='UNKNOWN'),watch_windows jsonb not null,missing_inputs jsonb not null default'[]',information_cutoff_at timestamptz not null,available_at timestamptz not null,classification_hash text not null,created_at timestamptz not null default now(),check(available_at<=information_cutoff_at),unique(news_revision_id,policy_version));
create table public.catalyst_classification_facts(id uuid primary key default gen_random_uuid(),classification_id uuid not null references public.catalyst_classifications(id),fact_index integer not null,fact_type text not null,fact_value jsonb not null,unit text,currency text,source_text text not null,evidence_revision_id uuid not null references public.news_article_revisions(id),created_at timestamptz not null default now(),unique(classification_id,fact_index));
create or replace function public.prevent_catalyst_classification_mutation()returns trigger language plpgsql as $$begin raise exception'Catalyst classification history is immutable';end$$;create trigger catalyst_classifications_immutable before update or delete on public.catalyst_classifications for each row execute function public.prevent_catalyst_classification_mutation();create trigger catalyst_facts_immutable before update or delete on public.catalyst_classification_facts for each row execute function public.prevent_catalyst_classification_mutation();alter table public.catalyst_classifications enable row level security;alter table public.catalyst_classification_facts enable row level security;create policy "public read catalyst classifications" on public.catalyst_classifications for select using(true);create policy "public read catalyst facts" on public.catalyst_classification_facts for select using(true);grant select on public.catalyst_classifications,public.catalyst_classification_facts to anon,authenticated;grant all on public.catalyst_classifications,public.catalyst_classification_facts to service_role;
alter table public.scheduled_jobs drop constraint if exists scheduled_jobs_job_type_check;alter table public.scheduled_jobs add constraint scheduled_jobs_job_type_check check(job_type in('BASELINE_FORECAST','FORECAST_OUTCOME','FORECAST_PERFORMANCE','NEWS_INGESTION','CATALYST_CLASSIFICATION'));insert into public.scheduled_jobs(job_key,job_type,scheduler_version,interval_seconds,lease_seconds,status,next_run_at,rate_limit_budget)values('catalyst-classification-5m','CATALYST_CLASSIFICATION','forecast-scheduler-v1.2',300,240,'HEALTHY',now(),'{}')on conflict(job_key)do nothing;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure','simulation','historical_replay','forecast_catalyst','expert_knowledge','baseline_forecast','forecast_performance','forecast_scheduler','forecast_outcomes','specialist_agents','news_ingestion','catalyst_classification'));
